def transform(grid):
    """Extend each diagonal same-color pair away from the pattern center."""
    h, w = len(grid), len(grid[0])
    from collections import Counter
    bg = Counter(v for row in grid for v in row).most_common(1)[0][0]
    points = [(r, c) for r in range(h) for c in range(w) if grid[r][c] != bg]
    out = [row[:] for row in grid]
    if not points:
        return out
    center_r = sum(r for r, c in points) / len(points)
    center_c = sum(c for r, c in points) / len(points)
    for r in range(h):
        for c in range(w):
            color = grid[r][c]
            if color == bg:
                continue
            for dr, dc in ((1, 1), (1, -1)):
                rr, rc = r + dr, c + dc
                if not (0 <= rr < h and 0 <= rc < w and grid[rr][rc] == color):
                    continue
                d1 = (r - center_r) ** 2 + (c - center_c) ** 2
                d2 = (rr - center_r) ** 2 + (rc - center_c) ** 2
                if d1 >= d2:
                    y, x, sr, sc = r, c, -dr, -dc
                else:
                    y, x, sr, sc = rr, rc, dr, dc
                y += sr
                x += sc
                while 0 <= y < h and 0 <= x < w and out[y][x] == bg:
                    out[y][x] = color
                    y += sr
                    x += sc
    return out
